import{_ as a,c as n,o,ag as t}from"./chunks/framework.DZ_cNctr.js";const u=JSON.parse('{"title":"Changelog","description":"What changed in the Find Nuclei Viewer, newest first.","frontmatter":{"title":"Changelog","description":"What changed in the Find Nuclei Viewer, newest first."},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),s={name:"changelog.md"};function i(l,e,r,h,d,c){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><h2 id="_2026-08-21" tabindex="-1">2026-08-21 <a class="header-anchor" href="#_2026-08-21" aria-label="Permalink to &quot;2026-08-21&quot;">​</a></h2><ul><li><strong>Shared links now carry the whole view.</strong> What you see is what they see. <a href="/docs/guides/sharing.html#what-the-recipient-sees">Sharing Views</a></li><li><strong>Opening a link keeps your own settings.</strong> It changes only what the link names. <a href="/docs/guides/sharing.html">Sharing Views</a></li><li><strong>Links no longer switch on your own labels.</strong> Labels built into a dataset travel with the link. Ones you added yourself stay yours, and the viewer says when a link had one. <a href="/docs/guides/labels.html">Labels</a></li><li><strong>Z-projection travels in the link</strong>, over the whole stack or a slab of it. <a href="/docs/guides/z-projection.html">Z-Projection</a></li><li><strong>Fixed the mean projection.</strong> Deep stacks came out too dark. Worth re-checking anything you measured from one. <a href="/docs/guides/z-projection.html">Z-Projection</a></li><li><strong>Faster Z-projection on deep stacks</strong>, and easier on memory.</li><li><strong>New custom background colour picker.</strong> Black, white, greys, or any colour you like.</li><li><strong>Brightfield images now open on a white background by default.</strong></li><li><strong>A link naming some channels no longer blanks the others.</strong> They keep the settings you already had. <a href="/docs/guides/channels.html">Channels</a></li></ul><h2 id="_2026-08-14" tabindex="-1">2026-08-14 <a class="header-anchor" href="#_2026-08-14" aria-label="Permalink to &quot;2026-08-14&quot;">​</a></h2><ul><li><strong>Install the viewer like an app.</strong> Install it from your browser and it opens from the dock or start menu, in its own window, with no address bar and no tab to lose. <a href="/docs/install-and-offline.html#installing">Installing and Offline</a></li><li><strong>It works with no connection.</strong> The viewer&#39;s own program files are cached on first visit, so it starts and runs offline. Local files open on a plane or behind a firewall exactly as they do online. Remote URLs still need a network, for obvious reasons. <a href="/docs/install-and-offline.html#working-with-no-network">Installing and Offline</a></li><li><strong>Your images are never cached.</strong> Only the program is. Image data is read on demand and never written to the offline cache, by design.</li></ul><h2 id="_2026-08-11" tabindex="-1">2026-08-11 <a class="header-anchor" href="#_2026-08-11" aria-label="Permalink to &quot;2026-08-11&quot;">​</a></h2><ul><li><strong>Inverted display got consistent rules.</strong> INV swaps white and black, and only those: every other channel colour keeps its hue. The canvas background follows the toggle, and channel swatches show the colour that actually lands on the page. <a href="/docs/guides/channels.html">Channels</a></li><li><strong>Contour rendering is much faster on chunked masks.</strong> Label chunks are now read aligned and cached, so outlining no longer multiplies decompression work. Toggling contour, fill or colours reuses cached data instead of re-reading it. <a href="/docs/guides/labels.html">Labels</a></li><li><strong>Improved Contour rendering for large images when zoomed out.</strong> The black outline fades into the fill where objects get too small to hold it, so a plate overview shows coloured objects instead of a black mass.</li><li><strong>Clear All Data now clears everything</strong>, including annotation templates and UI preferences, and the confirmation lists exactly what goes before you commit.</li></ul><h2 id="_2026-08-10" tabindex="-1">2026-08-10 <a class="header-anchor" href="#_2026-08-10" aria-label="Permalink to &quot;2026-08-10&quot;">​</a></h2><ul><li><strong>Analytics and phenotyping.</strong> Attach a measurements table to a segmentation, colour objects by any column, filter by value, then group them into named phenotypes. <a href="/docs/guides/analytics-phenotyping.html">Analytics and Phenotyping</a></li><li><strong>Annotations and templates.</strong> Draw and measure regions in real units. Classify them with reusable colour, class and shortcut templates, and export as CSV or GeoJSON. <a href="/docs/guides/annotations.html">Annotations</a> · <a href="/docs/guides/templates.html">Annotation Templates</a></li><li><strong>Documentation.</strong> Fourteen guides with screenshots, plus a published spec for the analytics data format so other tools can emit something the viewer reads. <a href="/docs/guides/">Guides</a> · <a href="/docs/guides/analytics-format.html">Analytics Data Format</a></li></ul>',9)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
